.long-content-container {
  overflow-wrap: break-word; /* Prevents long words/URLs from breaking layout */
  /* Alternatively, for even more aggressive breaking, consider: */
  /* overflow-wrap: anywhere; */
}

/* For broader browser support, 'word-break: break-all;' can be used alongside or as a fallback for older browsers. */
.url-display {
  overflow-wrap: break-word;
  word-break: break-all;
}
